<?php require_once __DIR__ . '/../config.php'; require_once __DIR__ . '/../Models/Facture.php'; class FactureController { private $pdo; public function __construct($pdo){ $this->pdo = $pdo; } public function addFacture(Facture $f){ return $f->save($this->pdo); } public function updateFacture(Facture $f){ return $f->save($this->pdo); } public function deleteFacture($id){ return Facture::delete($this->pdo, $id); } public function listByEntretien($entretienId){ return Facture::findByEntretien($this->pdo, $entretienId); } public function getFacture($id){ return Facture::findById($this->pdo, $id); } public function listAllFactures(){ return Facture::findAll($this->pdo); } } ?>